def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []
    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if verb not in arities or len(tokens) != arities[verb]:
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            text = tokens[-1]
            if not text or any(c < "0" or c > "9" for c in text):
                rejected.append(index)
                continue

            # Parse in chunks, avoiding Python's integer-string digit limit.
            amount = 0
            for start in range(0, len(text), 9):
                chunk = text[start:start + 9]
                amount = amount * (10 ** len(chunk)) + int(chunk)

            if verb != "open" and amount == 0:
                rejected.append(index)
                continue

        name = tokens[1]
        previous = accounts.get(name)

        if verb == "open":
            if previous is not None:
                rejected.append(index)
                continue
            updates = {name: (amount, False)}

        else:
            if previous is None:
                rejected.append(index)
                continue

            balance, frozen = previous

            if verb == "deposit":
                updates = {name: (balance + amount, frozen)}

            elif verb == "withdraw":
                if frozen or balance < amount:
                    rejected.append(index)
                    continue
                updates = {name: (balance - amount, frozen)}

            elif verb == "transfer":
                destination = tokens[2]
                target = accounts.get(destination)
                if (
                    name == destination
                    or target is None
                    or frozen
                    or balance < amount
                ):
                    rejected.append(index)
                    continue
                updates = {
                    name: (balance - amount, frozen),
                    destination: (target[0] + amount, target[1]),
                }

            elif verb == "freeze":
                if frozen:
                    rejected.append(index)
                    continue
                updates = {name: (balance, True)}

            else:  # unfreeze
                if not frozen:
                    rejected.append(index)
                    continue
                updates = {name: (balance, False)}

        history.append([(key, accounts.get(key)) for key in updates])
        accounts.update(updates)

    return {name: state[0] for name, state in accounts.items()}, rejected
